window.__searchIndex = [{"k":"lesson","s":"prompt-dlp","t":"Prompt DLP under TLS inspection","m":2,"x":"Part 1: Seeing AI traffic · Module 2"},{"k":"section","s":"prompt-dlp","t":"1. The attack","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"2. Why it works","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"3. The control","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"4. Defaults and when to change them","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"5. What it proves, and what it doesn't","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"6. Prove it","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"7. Lab","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"8. Check your understanding","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"A secret past the scan limit","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"Change one thing and predict the output","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"Controls","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"Review checklist items","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"section","s":"prompt-dlp","t":"Sources","m":2,"x":"Prompt DLP under TLS inspection"},{"k":"check","s":"prompt-dlp","t":"Requests to approved AI destinations are decrypted and scanned","i":"dlp-01","v":"High","x":"A destination allowlist decides where data may go. It is not a substitute for looking at what is sent."},{"k":"check","s":"prompt-dlp","t":"The scanner reads content the way the destination will","i":"dlp-02","v":"High","x":"JSON escapes and declared base64 attachments are decoded before any detector runs. A body that does not decode is blocked."},{"k":"check","s":"prompt-dlp","t":"A body over the scan limit is blocked for AI destinations","i":"dlp-03","v":"High","x":"It is never passed unscanned. The limit is recorded and tested with a body one byte over it."},{"k":"check","s":"prompt-dlp","t":"Every AI host on the bypass list has an owner, a reason, a review date and a compensating control","i":"dlp-04","v":"Medium","x":"A pinned app is blocked, or allowed uninspected with an endpoint control named in the entry."},{"k":"check","s":"prompt-dlp","t":"Exfiltration tests run on a schedule against AI destinations","i":"dlp-05","v":"Medium","x":"They cover each case in section 6 of this lesson, including a clean prompt that must be allowed."},{"k":"control","s":"prompt-dlp","m":2,"v":"Standard","t":"Route outbound traffic through authenticated proxy servers at managed interfaces. NIST SP 800-53 Rev 5.2.0 control SC-7(8) requires this for the traffic and networks the organization defines, and its discussion names web content filtering devices as one of the most common such proxies."},{"k":"control","s":"prompt-dlp","m":2,"v":"Standard","t":"Prevent the exfiltration of information, and conduct exfiltration tests at a defined frequency. NIST SP 800-53 Rev 5.2.0 control SC-7(10), parts (a) and (b). Its discussion says prevention applies to both intentional and unintentional exfiltration, and lists data loss and data leakage prevention tools among the techniques."},{"k":"control","s":"prompt-dlp","m":2,"v":"Standard","t":"Enforce approved authorizations for information flows between connected systems. NIST SP 800-53 Rev 5.2.0 control AC-4. Its discussion includes limiting transfers between organizations based on data structures and content."},{"k":"control","s":"prompt-dlp","m":2,"v":"Baseline","t":"Decrypt and scan every request to an approved AI destination. An allowlist entry is not a reason to skip inspection."},{"k":"control","s":"prompt-dlp","m":2,"v":"Baseline","t":"Scan the decoded content: JSON string values and every attachment the request declares as base64, at minimum."},{"k":"control","s":"prompt-dlp","m":2,"v":"Baseline","t":"Block a body over the scan limit, and a body that does not decode, when the destination is an AI service."},{"k":"control","s":"prompt-dlp","m":2,"v":"Baseline","t":"Keep the bypass list empty for AI destinations. Block an app that pins its certificate unless an owner accepts the gap in writing."},{"k":"control","s":"prompt-dlp","m":2,"v":"Option","t":"Allow a pinned app uninspected, with an endpoint DLP control on the devices that run it and a review date on the bypass entry."},{"k":"control","s":"prompt-dlp","m":2,"v":"Option","t":"Coach instead of block for low-severity matches: show the user what was found and let them confirm, with the decision logged."},{"k":"code","s":"prompt-dlp","m":2,"t":"chat.assistant.example"},{"k":"code","s":"prompt-dlp","m":2,"t":"labs/prompt_dlp_lab.py"},{"k":"code","s":"prompt-dlp","m":2,"t":"py -3"},{"k":"code","s":"prompt-dlp","m":2,"t":"python3"},{"k":"code","s":"prompt-dlp","m":2,"t":"KEY_PATTERN"},{"k":"code","s":"prompt-dlp","m":2,"t":"stack/prompt-dlp/README.md"},{"k":"code","s":"prompt-dlp","m":2,"t":"texts_in"},{"k":"code","s":"prompt-dlp","m":2,"t":"yield value[\"data\"]"},{"k":"code","s":"prompt-dlp","m":2,"t":"allow: nothing found"},{"k":"code","s":"prompt-dlp","m":2,"t":"dlp-02"},{"k":"code","s":"prompt-dlp","m":2,"t":"SCAN_LIMIT = 64 * 1024"},{"k":"code","s":"prompt-dlp","m":2,"t":"SCAN_LIMIT = 128 * 1024"},{"k":"code","s":"prompt-dlp","m":2,"t":"block: secret found"},{"k":"code","s":"prompt-dlp","m":2,"t":"dlp-03"},{"k":"code","s":"prompt-dlp","m":2,"t":"BYPASS = {PINNED_HOST}"},{"k":"code","s":"prompt-dlp","m":2,"t":"BYPASS = set()"},{"k":"code","s":"prompt-dlp","m":2,"t":"allow: not inspected"},{"k":"code","s":"prompt-dlp","m":2,"t":"block: body could not be decoded"},{"k":"code","s":"prompt-dlp","m":2,"t":"dlp-04"},{"k":"term","s":"base64","t":"Base64","x":"A way of writing any bytes using only 64 printable characters, so a file can travel inside a text format such as JSON. It is an encoding, not encryption: anyone can decode it, but a pattern written for the original text will not match the encoded form."},{"k":"term","s":"certificate-pinning","t":"Certificate pinning","x":"An application accepting only a specific certificate or key for a server, instead of any certificate its trust store accepts. A pinned application refuses the certificate a TLS-inspecting gateway presents, so it fails to connect rather than being inspected."},{"k":"term","s":"data-loss-prevention","t":"Data loss prevention (DLP)","x":"Controls that look at data leaving an organization and block or record what matches a policy, such as a secret, a card number or a classification label. A DLP scan only finds what its detectors describe, in the encodings it decodes."},{"k":"term","s":"inspection-bypass-list","t":"Inspection bypass list","x":"The hosts or applications a gateway passes without decrypting, usually because they break under TLS inspection. Every entry is traffic the gateway cannot scan, so each one needs an owner and a reason."},{"k":"term","s":"sase","t":"SASE","x":"Secure access service edge. A way of delivering network security as one cloud service: web filtering, data loss prevention, zero trust network access, firewalling and wide area networking, under one policy. It is a delivery model built from separate functions, which is how this course teaches it."},{"k":"term","s":"secure-web-gateway","t":"Secure web gateway (SWG)","x":"A proxy that an organization's web traffic passes through on its way to the internet. It decides which destinations are allowed and, with TLS inspection, what content may be sent to them."},{"k":"term","s":"tls-inspection","t":"TLS inspection","x":"A gateway ending the client's encrypted session, reading the request, and opening its own encrypted session to the destination. The client must trust a certificate authority the organization controls. Without it, a gateway sees the destination host but not the content."}];
